using DobleCommander;
var root=Path.Combine(Path.GetTempPath(),"DobleCommander-mirror-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);int passed=0;
void Assert(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);passed++;}
string Dir(string name){var p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
void Write(string folder,string relative,string text){var path=Path.Combine(folder,relative);Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,text);}
var logs=Dir("logs");var source=Dir("source");var target=Dir("target");
Write(source,"same.txt","Identical");Write(target,"same.txt","Identical");Write(source,"update.txt","new version");Write(target,"update.txt","old version");File.SetLastWriteTimeUtc(Path.Combine(target,"same.txt"),File.GetLastWriteTimeUtc(Path.Combine(source,"same.txt")));File.SetLastWriteTimeUtc(Path.Combine(target,"update.txt"),File.GetLastWriteTimeUtc(Path.Combine(source,"update.txt")).AddDays(-1));
Write(source,"new/data.txt","New data");Directory.CreateDirectory(Path.Combine(source,"empty"));Write(source,"flip-to-file","A file now");Write(target,"flip-to-file/old.txt","Old directory");Write(source,"flip-to-dir/data.txt","Directory now");Write(target,"flip-to-dir","Old file");Write(target,"deleted.txt","Removed at origin");Write(target,"obsolete/nested/old.txt","Old tree");
var manifest=await MirrorPlanner.ReadSourceAsync(source);var preview=await MirrorPlanner.PreviewAsync(manifest,target);
Assert(preview.CopyFiles.Any(f=>f.Relative=="update.txt"),"metadata detects an updated file by its timestamp");Assert(!preview.CopyFiles.Any(f=>f.Relative=="same.txt"),"unchanged content is not recopied");Assert(preview.BlockerRoots.Length==2,"file-folder type conflicts are planned");Assert(File.Exists(Path.Combine(target,"deleted.txt"))&&File.ReadAllText(Path.Combine(target,"update.txt"))=="old version","preview does not mutate destination");
var job=new MirrorJob(preview,false,logs);await job.RunAsync();Assert(job.Status.State=="Completado","mirror completes including type replacements");
var final=MirrorPlanner.Scan(target);Assert(final.Count==manifest.Nodes.Count&&manifest.Nodes.All(p=>final.TryGetValue(p.Key,out var node)&&node.Directory==p.Value.Directory&&node.Size==p.Value.Size),"final hierarchy matches source including empty folders");
Assert((await Task.WhenAll(manifest.Plan.Files.Select(async f=>{var actual=await TestFiles.Hash(Path.Combine(target,f.Relative),default);var expected=await TestFiles.Hash(f.Source,default);return actual.SequenceEqual(expected);}))).All(x=>x),"all destination contents match source hashes checked only by the test");Assert(!File.Exists(Path.Combine(target,"deleted.txt"))&&!Directory.Exists(Path.Combine(target,"obsolete")),"removed source files and folders are removed from destination");Assert(!Directory.EnumerateDirectories(target,".DobleCommander-espejo-*").Any(),"successful mirror purges its recovery directory");
var second=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(source),target);Assert(second.CopyFiles.Length==0&&second.RemoveRoots.Length==0&&second.BlockerRoots.Length==0,"second mirror is incremental and has no data transfers");var repeat=new MirrorJob(second,false,logs);await repeat.RunAsync();Assert(repeat.Status.State=="Completado"&&repeat.Status.Written==0,"unchanged mirror writes zero content bytes");
var changedSource=Dir("changed-source");var changedTarget=Dir("changed-target");Write(changedSource,"file.txt","original");Write(changedTarget,"keep-until-success.txt","Must survive");var changedPreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(changedSource),changedTarget);Write(changedSource,"file.txt","changed after preview");var changedJob=new MirrorJob(changedPreview,false,logs);await changedJob.RunAsync();Assert(changedJob.Status.State=="Error"&&File.Exists(Path.Combine(changedTarget,"keep-until-success.txt")),"changed source aborts before deleting extras");
var changedDestination=Dir("changed-destination");Write(changedDestination,"old.txt","Keep");var changedDestPreview=await MirrorPlanner.PreviewAsync(manifest,changedDestination);Write(changedDestination,"external.txt","Created after preview");var changedDestJob=new MirrorJob(changedDestPreview,false,logs);await changedDestJob.RunAsync();Assert(changedDestJob.Status.State=="Error"&&File.Exists(Path.Combine(changedDestination,"old.txt"))&&File.Exists(Path.Combine(changedDestination,"external.txt")),"changed destination invalidates confirmed plan");
var emptySource=Dir("empty-source");var emptyTarget=Dir("empty-target");Write(emptyTarget,"old/f.txt","Old");var emptyPreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(emptySource),emptyTarget);var emptyJob=new MirrorJob(emptyPreview,false,logs);await emptyJob.RunAsync();Assert(emptyJob.Status.State=="Completado"&&!Directory.EnumerateFileSystemEntries(emptyTarget).Any(),"explicit empty-source mirror removes destination data");
var goneSource=Dir("gone-empty-source");var goneTarget=Dir("gone-target");Write(goneTarget,"keep.txt","Must survive");var gonePreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(goneSource),goneTarget);Directory.Delete(goneSource);var goneJob=new MirrorJob(gonePreview,false,logs);await goneJob.RunAsync();Assert(goneJob.Status.State=="Error"&&File.Exists(Path.Combine(goneTarget,"keep.txt")),"disappeared empty source is not treated as intentional empty mirror");
var lowSource=Dir("low-source");var lowTarget=Dir("low-target");Write(lowSource,"new.txt","new");Write(lowTarget,"obsolete.txt","obsolete-data");var lowPreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(lowSource),lowTarget,freeBytes:_=>0);Assert(!lowPreview.Fits(false)&&lowPreview.Fits(true),"space estimate distinguishes deferred and early deletion");var noRoom=new MirrorJob(lowPreview,false,logs,freeBytes:_=>0);await noRoom.RunAsync();Assert(noRoom.Status.State=="Error"&&File.Exists(Path.Combine(lowTarget,"obsolete.txt")),"insufficient space stops before any deletion");var early=new MirrorJob(lowPreview,true,logs,freeBytes:_=>0);await early.RunAsync();Assert(early.Status.State=="Completado"&&File.Exists(Path.Combine(lowTarget,"new.txt"))&&!File.Exists(Path.Combine(lowTarget,"obsolete.txt")),"explicit early deletion reclaims obsolete content before copying");
var impossibleTarget=Dir("impossible-target");Write(impossibleTarget,"obsolete.txt","x");var impossiblePreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(lowSource),impossibleTarget,freeBytes:_=>0);var impossible=new MirrorJob(impossiblePreview,true,logs,freeBytes:_=>0);await impossible.RunAsync();Assert(impossible.Status.State=="Error"&&File.Exists(Path.Combine(impossibleTarget,"obsolete.txt")),"even early deletion is refused if reclaimable bytes are insufficient");
var cancelTarget=Dir("cancel-target");Write(cancelTarget,"old.txt","Keep");var cancelPreview=await MirrorPlanner.PreviewAsync(manifest,cancelTarget);var cancelled=new MirrorJob(cancelPreview,false,logs);cancelled.Cancel();await cancelled.RunAsync();Assert(cancelled.Status.State=="Cancelado"&&File.Exists(Path.Combine(cancelTarget,"old.txt")),"cancel before execution leaves destination untouched");
bool rejected=false;try{MirrorPlanner.ValidateRoots(source,[Path.Combine(source,"inside")]);}catch(IOException){rejected=true;}Assert(rejected,"mirror rejects overlapping source and destination");rejected=false;try{MirrorPlanner.ValidateRoots(source,[target,Path.Combine(target,"child")]);}catch(IOException){rejected=true;}Assert(rejected,"mirror rejects overlapping destination roots");rejected=false;try{MirrorPlanner.ValidateRoots(source,[target],[Path.Combine(target,"application")]);}catch(IOException){rejected=true;}Assert(rejected,"mirror rejects destinations containing protected paths");
var recoveryTarget=Dir("old-recovery-target");Write(recoveryTarget,".DobleCommander-espejo-old/keep.txt","Recovery data");rejected=false;try{await MirrorPlanner.PreviewAsync(manifest,recoveryTarget);}catch(IOException){rejected=true;}Assert(rejected&&File.Exists(Path.Combine(recoveryTarget,".DobleCommander-espejo-old/keep.txt")),"previous recovery data cannot be silently deleted by another mirror");
var parallelA=Dir("parallel-a");var parallelB=Dir("parallel-b");Write(parallelA,"obsolete.txt","A");Write(parallelB,"obsolete.txt","B");var parallelJobs=new[]{new MirrorJob(await MirrorPlanner.PreviewAsync(manifest,parallelA),false,logs),new MirrorJob(await MirrorPlanner.PreviewAsync(manifest,parallelB),false,logs)};await Task.WhenAll(parallelJobs.Select(j=>j.RunAsync()));Assert(parallelJobs.All(j=>j.Status.State=="Completado")&&MirrorPlanner.Scan(parallelA).Count==manifest.Nodes.Count&&MirrorPlanner.Scan(parallelB).Count==manifest.Nodes.Count,"multiple destination mirrors run in parallel and converge to one source");
string identity="original-device";var identityTarget=Dir("identity-target");Write(identityTarget,"keep.txt","Must survive");var identityManifest=await MirrorPlanner.ReadSourceAsync(source,_=>identity);var identityPreview=await MirrorPlanner.PreviewAsync(identityManifest,identityTarget,_=>identity);identity="other-device";var identityJob=new MirrorJob(identityPreview,false,logs,_=>identity);await identityJob.RunAsync();Assert(identityJob.Status.State=="Error"&&File.Exists(Path.Combine(identityTarget,"keep.txt")),"device identity change blocks mirror before deletion");
var largeSource=Dir("large-source");using(var f=File.Create(Path.Combine(largeSource,"large.bin")))f.SetLength(256L*1024*1024);var largeTarget=Dir("large-target");Write(largeTarget,"keep-until-success.txt","Must survive");var largePreview=await MirrorPlanner.PreviewAsync(await MirrorPlanner.ReadSourceAsync(largeSource),largeTarget);var largeJob=new MirrorJob(largePreview,false,logs);var largeTask=largeJob.RunAsync();var deadline=DateTime.UtcNow.AddSeconds(15);while(largeJob.Status.Written<1024*1024&&!largeTask.IsCompleted){if(DateTime.UtcNow>deadline)throw new Exception("Mirror progress timeout");await Task.Delay(1);}largeJob.Pause();await Task.Delay(80);var before=largeJob.Status.Written;await Task.Delay(80);Assert(largeJob.Status.State=="Pausado"&&before==largeJob.Status.Written,"mirror pauses active file copy");largeJob.Cancel();await largeTask;Assert(largeJob.Status.State=="Cancelado"&&File.Exists(Path.Combine(largeTarget,"keep-until-success.txt"))&&!Directory.EnumerateFiles(largeTarget,"*.partial",SearchOption.AllDirectories).Any(),"mid-copy cancellation removes temporary output and preserves obsolete files");
var sharedA=preview with{Destination=Path.Combine(root,"shared-a"),Identity="shared-volume",FreeBytes=3,PeakBytes=3,ReclaimableBytes=2};var sharedB=preview with{Destination=Path.Combine(root,"shared-b"),Identity="shared-volume",FreeBytes=3,PeakBytes=3,ReclaimableBytes=2};Assert(!MirrorPlanner.FitsTogether([sharedA,sharedB],false)&&MirrorPlanner.FitsTogether([sharedA,sharedB],true),"space requirements are aggregated for destinations sharing a volume");Assert(MirrorPlanner.RequiresEarlyPrune(sharedA,[sharedA,sharedB])&&MirrorPlanner.RequiresEarlyPrune(sharedB,[sharedA,sharedB]),"early pruning is selected for all affected destinations on an overcommitted volume");Assert(MirrorPlanner.FitsTogether([sharedA,sharedB with{Identity="independent-volume"}],false),"independent volumes have independent free-space budgets");
Console.WriteLine($"{passed} mirror assertions passed. No user volume was mirrored.");Directory.Delete(root,true);
